// ── immediate action feedback ───────────────────────────────────────────────
// Every server-backed interaction should acknowledge the user's gesture before
// the network has a chance to answer. Event listeners do not expose their async
// Promise to the browser, so remember the control that originated the current
// event; feedbackFetch() can then bind the request to that control without every
// one of the console's mutation handlers reinventing a spinner/disabled state.
// The origin expires when the event's task ends (a zero-delay timeout), so
// background refreshes and auto-save requests never make an unrelated,
// previously-clicked button look busy. It must outlive microtasks: for real
// input the browser runs a microtask checkpoint after every listener, i.e.
// between this capture listener and the control's own handler.
let interactionOrigin = null;
let interactionOriginEpoch = 0;
let actionProgressCount = 0;
const actionFeedbackStates = new WeakMap();

function actionableControl(target, event) {
  if (!target?.closest) return null;
  if (event?.type === 'submit')
    return event.submitter || target.querySelector?.('button[type="submit"],input[type="submit"]') || target;
  return target.closest('button,input,select,textarea,[role="button"],a[data-spa],.task-row');
}

function rememberInteractionOrigin(event) {
  const control = actionableControl(event.target, event);
  if (!control) return;
  // Keep the original control as the event target (pointer-events:none can send
  // a repeat click through to a clickable row underneath). Swallow repeats at
  // capture time while the first request is visibly pending.
  // Only activation keys count; ordinary typing must never be swallowed, and a
  // paste/drop into a text field is an upload, not an action on that field —
  // marking it pending would disable the field the user is typing in.
  if (event.type === 'keydown' && (/^(?:INPUT|TEXTAREA)$/.test(control.tagName || '') || control.isContentEditable)) return;
  if (event.type === 'keydown' && !['Enter', ' '].includes(event.key)) return;
  if ((event.type === 'paste' || event.type === 'drop') && /^(?:INPUT|TEXTAREA)$/.test(control.tagName || '')) return;
  if (control.classList?.contains('action-pending')) {
    event.preventDefault?.();
    event.stopImmediatePropagation?.();
    return;
  }
  const epoch = ++interactionOriginEpoch;
  interactionOrigin = control;
  setTimeout(() => {
    if (interactionOriginEpoch === epoch) interactionOrigin = null;
  }, 0);
}

function installInteractionTracking() {
  ['pointerdown', 'click', 'change', 'submit', 'paste', 'drop'].forEach((type) =>
    document.addEventListener(type, rememberInteractionOrigin, true));
  document.addEventListener('keydown', rememberInteractionOrigin, true);
}
if (typeof document !== 'undefined') installInteractionTracking();

function actionLabel(control) {
  return String(control?.getAttribute?.('aria-label') || control?.title || control?.textContent || 'Action')
    .replace(/\s+/g, ' ').trim().slice(0, 80) || 'Action';
}

function beginActionFeedback(control = interactionOrigin) {
  const progress = typeof document !== 'undefined' ? document.getElementById('action-progress') : null;
  actionProgressCount++;
  if (progress) {
    progress.hidden = false;
    progress.dataset.outcome = '';
    progress.setAttribute('aria-label', `${actionLabel(control)} in progress`);
  }
  if (!control || !control.isConnected) return { control: null, startedAt: Date.now() };

  const state = actionFeedbackStates.get(control) || {
    count: 0,
    ariaBusy: control.getAttribute?.('aria-busy'),
    ariaDisabled: control.getAttribute?.('aria-disabled'),
  };
  state.count++;
  actionFeedbackStates.set(control, state);
  control.classList?.remove('action-succeeded', 'action-failed');
  control.classList?.add('action-pending');
  control.setAttribute?.('aria-busy', 'true');
  control.setAttribute?.('aria-disabled', 'true');
  return { control, startedAt: Date.now() };
}

function finishActionFeedback(ticket, ok) {
  const elapsed = Date.now() - ticket.startedAt;
  // Keep very fast responses perceptible instead of flashing for a single frame.
  setTimeout(() => {
    actionProgressCount = Math.max(0, actionProgressCount - 1);
    const progress = typeof document !== 'undefined' ? document.getElementById('action-progress') : null;
    if (progress && actionProgressCount === 0) {
      progress.dataset.outcome = ok ? 'success' : 'error';
      setTimeout(() => {
        if (actionProgressCount === 0) {
          progress.hidden = true;
          progress.dataset.outcome = '';
          progress.setAttribute('aria-label', 'Action in progress');
        }
      }, 420);
    }

    const { control } = ticket;
    const state = control && actionFeedbackStates.get(control);
    if (!control || !state) return;
    state.count = Math.max(0, state.count - 1);
    if (state.count) return;
    actionFeedbackStates.delete(control);
    control.classList?.remove('action-pending');
    control.classList?.add(ok ? 'action-succeeded' : 'action-failed');
    if (state.ariaBusy == null) control.removeAttribute?.('aria-busy');
    else control.setAttribute?.('aria-busy', state.ariaBusy);
    if (state.ariaDisabled == null) control.removeAttribute?.('aria-disabled');
    else control.setAttribute?.('aria-disabled', state.ariaDisabled);
    setTimeout(() => control.classList?.remove('action-succeeded', 'action-failed'), 700);
  }, Math.max(0, 180 - elapsed));
}

function feedbackFetch(input, opts = {}) {
  const ticket = interactionOrigin ? beginActionFeedback(interactionOrigin) : null;
  return fetch(input, opts).then(
    (response) => { if (ticket) finishActionFeedback(ticket, response.ok); return response; },
    (error) => { if (ticket) finishActionFeedback(ticket, false); throw error; },
  );
}

// Non-principal attempts are intentionally absent from S.tasks because the list
// has one row per logical task. Page lookups must also consult the loaded group.
function taskRecord(id) {
  return (S.attemptGroup?.attempts || []).find((t) => t.id === id)
    || (S.tasks || []).find((t) => t.id === id)
    || (S.searchResult?.tasks || []).find((t) => t.id === id);
}

// ── URL routing (SPEC §10.6) ────────────────────────────────────────────────
// Every page is a host-owned route; the browser URL is the single source of truth
// for {organization, project, tab, open task}. Workflows/coordinators never own a
// URL — a page like the merge queue is a first-party route that projects
// coordinator/task state. Organization-owned pages live under the organization's
// slug; the user-owned profile does not. Projects are addressed by a slug of their
// name; tasks are numbered per project.
// Scheme:
//   /                                    → home (redirects into the current org's home)
//   /profile                             → the current user's profile
//   /installation                        → global operator-only installation controls
//   /<org>                               → org home: every project's tasks, for:me by default
//   /<org>/insights                      → organization insights (/<org>/dashboard redirects here)
//   /<org>/settings                      → organization settings
//   /<org>/inbox                         → inbox
//   /<org>/wiki                          → organization wiki
//   /<org>/<project>                     → task list (also /queue, /activity, /wiki, /settings)
//   /<org>/<project>/tasks/:num          → the task's own page (permalink)
//   /<org>/<project>/tasks/:num/:tab     → the task page pinned to one of its tabs
// A task list's query rides in ?q=; no ?q means the default `for:me`, and an
// empty ?q= is "All".
// Pre-organization URLs (/dashboard, /organization, /projects/:name/…) are still
// parsed and then canonicalised to the org form.
function slugify(s) {
  return String(s || '').normalize('NFC').toLowerCase().replace(/[^\p{L}\p{N}\p{M}]+/gu, '-').replace(/^-+|-+$/g, '').slice(0, 48) || 'item';
}
function projectSlug(p) { return p ? slugify(p.name) : ''; }
function projectPath(p) { return p ? [p.folder, p.name].filter(Boolean).join('/') : ''; }
function projectById(pid) { return (S.projects || []).find((p) => p.id === pid); }
function firstProjectForOrganization(organizationId) {
  return (S.projects || []).find((p) => p.organizationId === organizationId);
}
// Resolve a URL slug back to a project, optionally scoped to one organization
// (project slugs need only be unique within their org). Matches the slugified name
// (the common, human case), falling back to a raw project id for safety. On a slug
// collision the first-created project wins (names are expected distinct).
function projectBySlug(slug, organizationId) {
  const s = slugify(slug);
  const pool = (S.projects || []).filter((p) => !organizationId || p.organizationId === organizationId);
  return pool.find((p) => slugify(p.name) === s) || pool.find((p) => p.id === slug);
}

// Organizations own the top path segment. They carry a persisted slug; fall back
// to a slug of the name for older records that predate it.
function orgSlug(o) { return o ? (o.slug || slugify(o.name)) : ''; }
function organizationById(id) { return (S.organizations || []).find((o) => o.id === id); }
// Re-authorization is always offered once OAuth is configured. `userAuthorized`
// only reports that a stored credential EXISTS, not that GitHub still accepts
// it — so hiding this button whenever one exists left no escape hatch for a
// token invalidated server-side (revocation, secret rotation, a single-use
// refresh chain consumed by a concurrent instance). Re-authorizing a healthy
// grant is idempotent, so there is no cost to keeping the affordance visible.
function githubAuthorizeButton(githubApp, id) {
  if (!githubApp?.oauthConfigured) return '';
  const [label, tip] = githubApp.userAuthorized ? ['Reconnect', 'Reconnect your GitHub account'] : ['Connect', 'Connect your GitHub account'];
  return `<button class="btn sm" id="${id}" title="${tip}">${label}</button>`;
}
// A renamed organization keeps answering to its old slugs (applyRoute then
// rewrites the URL to the current one).
function organizationBySlug(slug) {
  const s = slugify(slug);
  const organizations = S.organizations || [];
  return organizations.find((o) => orgSlug(o) === s) || organizations.find((o) => o.id === slug)
    || organizations.find((o) => (o.previousSlugs || []).includes(s));
}
// The current URL with its organization segment replaced by `org`'s slug.
function pathWithOrganization(org) {
  const [, , ...rest] = location.pathname.split('/');
  return `/${[orgSlug(org), ...rest].join('/')}${location.search}${location.hash}`;
}
// Where a route that names an organization by a slug it had before a rename
// now lives; '' when the route is already current.
function renamedOrganizationPath(route) {
  const org = route.org && organizationBySlug(route.org);
  return org && slugify(route.org) !== orgSlug(org) && org.id !== route.org ? pathWithOrganization(org) : '';
}
// The organization whose slug prefixes every URL — the one selected in the
// switcher, else the org owning the current project, else the first known org.
function currentOrg() {
  return organizationById(S.organizationId)
    || organizationById(projectById(S.projectId)?.organizationId)
    || organizationById(S.defaultOrganizationId)
    || (S.organizations || [])[0];
}

// The shell outlives every in-app navigation, so changing route state does not
// recreate its organization picker. Keep that persistent control aligned with
// the organization whose data the route selected (including the initial deep
// link and Back/Forward navigation).
function syncOrganizationSwitcher() {
  const switcher = $('#org-switcher');
  const organization = currentOrg();
  if (switcher && organization) switcher._sync?.();
}
// `/<org>` prefix for the current (or a given) organization; '' when none is known.
function orgBase(org = currentOrg()) { return org ? `/${orgSlug(org)}` : ''; }

/** Tabs that belong to the selected project (the router reads them from URLs,
 *  the rail highlights the project, the main pane shows its tab bar). One list
 *  so they never drift apart again. */
const PROJECT_SCOPED_TABS = ['tasks', 'queue', 'activity', 'wiki', 'avatars', 'settings'];
const PROJECT_TAB_COMMANDS = { tasks: 'nav.tasks', queue: 'nav.queue', wiki: 'nav.wiki', settings: 'nav.settings' };
// The query a task list opens with: what needs the signed-in person.
const DEFAULT_LIST_QUERY = 'for:me';
// Second-segment words that name an organization-level view rather than a project.
const ORG_VIEWS = { insights: 'insights', settings: 'organization', inbox: 'inbox', wiki: 'orgwiki' };

// Parse an in-app URL — a path, optionally with its `?…` query string — into the
// page it names. The tasks list's whole search state (free text, filters, group,
// sort) is the one query string in `?q=`, so it rides along as `q` on every
// project route: a search is just a URL.
function decodeRoutePart(value, component = false) {
  try { return component ? decodeURIComponent(value) : decodeURI(value); }
  catch { return value; }
}

function parseRoute(url) {
  let [pathname, search = ''] = String(url).split('?');
  try { pathname = decodeURI(pathname); } catch {}
  const query = new URLSearchParams(search);
  const q = query.has('q') ? query.get('q') : DEFAULT_LIST_QUERY;
  const seg = pathname.replace(/\/+$/, '').split('/').filter(Boolean);
  if (!seg.length) return { name: 'home' };
  if (seg[0] === 'invite') return { name: 'invite' };
  if (seg[0] === 'profile') return { name: 'profile', ...(seg[1] ? { userId: seg[1] } : {}) };
  if (seg[0] === 'installation') return { name: 'installation' };
  // Pre-organization URLs — resolved, then canonicalised to the org form.
  if (seg[0] === 'dashboard') return { name: 'global', tab: 'insights', legacy: true };
  if (seg[0] === 'settings' || seg[0] === 'organization') return { name: 'global', tab: 'organization', legacy: true };
  // The bell's page: what waits on you in every organization, so above them all.
  if (seg[0] === 'inbox') return { name: 'global', tab: 'inbox', q, ...(seg[1] ? { legacy: true } : {}) };
  if (seg[0] === 'projects' && seg[1]) {
    const tab = PROJECT_SCOPED_TABS.includes(seg[2]) ? seg[2] : 'tasks';
    const taskKey = seg[2] === 'tasks' && seg[3] ? seg[3] : null;
    const taskTab = taskKey && TASK_TABS.some((t) => t.key === seg[4]) ? seg[4] : null;
    const taskFile = taskKey && seg[4] === 'file' ? fileRouteTarget(query) : null;
    return { name: 'project', slug: seg[1], tab, taskKey, taskTab, q, legacy: true, ...(taskFile ? { taskFile } : {}) };
  }
  // New scheme: /<org>/… — everything is namespaced under the organization slug.
  const org = seg[0];
  if (!seg[1]) return { name: 'global', org, tab: 'home', q };       // /<org> → org home
  // Profile used to be organization-prefixed. It never belonged to that tenant,
  // so recognize old bookmarks without carrying their org into application state.
  if (seg[1] === 'profile') return { name: 'profile', legacy: true };
  // Insights replaced the old Dashboard; keep its bookmarks working.
  if (seg[1] === 'dashboard') return { name: 'global', org, tab: 'insights', legacy: true };
  // The inbox was once one organization's, with a tab per kind of notification.
  if (ORG_VIEWS[seg[1]] === 'inbox') return { name: 'global', tab: 'inbox', q, legacy: true };
  if (ORG_VIEWS[seg[1]]) return { name: 'global', org, tab: ORG_VIEWS[seg[1]] };
  const tab = PROJECT_SCOPED_TABS.includes(seg[2]) ? seg[2] : 'tasks';
  const taskKey = seg[2] === 'tasks' && seg[3] ? seg[3] : null;
  const taskTab = taskKey && TASK_TABS.some((t) => t.key === seg[4]) ? seg[4] : null;
  const taskFile = taskKey && seg[4] === 'file' ? fileRouteTarget(query) : null;
  const wikiView = tab === 'wiki' ? wikiViewFromQuery(query) : '';
  const avatarId = tab === 'avatars' && seg[3] ? seg[3] : null;
  return { name: 'project', org, slug: seg[1], tab, taskKey, taskTab, q, ...(taskFile ? { taskFile } : {}),
    ...(wikiView ? { wikiView } : {}), ...(avatarId ? { avatarId } : {}) };
}

// Which branch the project wiki shows is part of the page, so it lives in the
// URL: `?task=<num>` (a task's live checkout) or `?branch=<name>`; the open
// entry rides in the hash.
function wikiViewFromQuery(query) {
  const task = query.get('task'), branch = query.get('branch');
  return task ? `task:${task}` : branch ? `branch:${branch}` : '';
}

function wikiRoute(pid, view = '', entry = '') {
  const [kind, ...rest] = String(view).split(':');
  const value = rest.join(':');
  const query = kind === 'task' && value ? `?task=${encodeURIComponent(value)}`
    : kind === 'branch' && value ? `?branch=${encodeURIComponent(value)}` : '';
  return `${projectRoute(pid, 'wiki')}${query}${entry ? `#${encodeURIComponent(entry)}` : ''}`;
}

// An open Avatar: /<org>/<project>/avatars/<id>; the list without an id.
function avatarRoute(pid, avatarId) {
  return `${projectRoute(pid, 'avatars')}${avatarId ? `/${encodeURIComponent(avatarId)}` : ''}`;
}

function fileRouteTarget(query) {
  const path = query.get('path') || '';
  const lineValue = query.get('line');
  const line = lineValue && /^\d+$/.test(lineValue) && Number(lineValue) > 0 ? Number(lineValue) : undefined;
  return { path, ...(line ? { line } : {}) };
}

// The `/<org>/<project>` prefix every project URL builds on ('' when unknown).
function projectBase(pid) {
  const p = projectById(pid);
  return p ? `${orgBase(organizationById(p.organizationId)) || orgBase()}/${projectSlug(p)}` : '';
}

// The list/tab route for a project (by id): /<org>/<project> for the default
// tasks tab, with the tab appended for the others. The tasks list additionally
// carries the working query in `?q=`, so its links are the durable, shareable
// form of a search — and so moving between tabs (or back from a task) restores
// the exact filtered/grouped/sorted view. It defaults to the query in hand,
// which belongs to the project currently on screen and to no other.
function projectRoute(pid, tab = 'tasks', q = pid === S.searchScope ? S.search : DEFAULT_LIST_QUERY) {
  const base = projectBase(pid);
  if (!base) return globalRoute('insights');
  if (tab !== 'tasks') return `${base}/${tab}`;
  return listRoute(base, q);
}

// A task list's URL: the default query (`for:me`) is the bare path, anything
// else — "All" (the empty query) included — is spelled out in ?q=.
function listRoute(base, q) {
  return q === DEFAULT_LIST_QUERY ? base : `${base}?q=${encodeQuery(q || '')}`;
}

// The organization home — every project's tasks in one list — at /<org>.
function homeRoute(org = currentOrg(), q) {
  const query = q ?? (S.searchScope === 'org:' + org?.id ? S.search : DEFAULT_LIST_QUERY);
  const base = orgBase(org);
  return base ? listRoute(base, query) : '/';
}

// Query strings are meant to be read and hand-edited in the address bar, so we
// keep the characters that are legal there legal-looking: ':' and ',' survive
// unescaped and a space rides as '+' (which URLSearchParams decodes back).
function encodeQuery(q) {
  return encodeURIComponent(q).replace(/%3A/g, ':').replace(/%2C/g, ',').replace(/%20/g, '+');
}

// An organization-level route (insights / settings / inbox) under the current
// (or a given) org's slug. Internal tab key 'organization' → URL segment 'settings'.
function globalRoute(tab, org = currentOrg()) {
  const seg = tab === 'organization' ? 'settings' : tab === 'orgwiki' ? 'wiki' : tab;
  return `${orgBase(org)}/${seg}`;
}

// Destination for an explicit organization-picker selection. Build it from the
// selected organization rather than mutating S first; applyRoute then performs
// the context switch from the URL as the single source of truth.
function organizationLandingRoute(organizationId) {
  const organization = organizationById(organizationId);
  return organization ? homeRoute(organization, DEFAULT_LIST_QUERY) : null;
}

function installationRoute() { return '/installation'; }

// The profile belongs to the signed-in user, not to the selected organization.
function profileRoute(userId) { return userId ? `/profile/${encodeURIComponent(userId)}` : '/profile'; }

// The bell's page, /inbox: the Home list over every organization, its query in ?q=.
function inboxRoute(q) {
  return listRoute('/inbox', q ?? (S.searchScope === 'all' ? S.search : DEFAULT_LIST_QUERY));
}

// The URL we are on, query string included — the full identity of the current
// view, since a search lives in `?q=`.
function currentPath() { return location.pathname + location.search; }

// Navigate: update the URL then reconcile app state to it. `replace` swaps the
// current history entry instead of pushing a new one.
function go(path, opts = {}) {
  closeTaskFormPage();
  if (path !== currentPath()) {
    history[opts.replace ? 'replaceState' : 'pushState']({ kx: 1 }, '', path);
  }
  return applyRoute();
}

// The task form page floats over #main with the shell (topbar/rail) still live
// behind it, so the user can navigate mid-edit. Any navigation closes it like
// leaving any other page — via its close button, which flushes the draft.
function closeTaskFormPage() {
  const page = $('#tf-page');
  if (!page) return;
  page.dataset.navigating = 'true'; // a draft's own page must not navigate again on close
  $('#tf-close')?.click();
}

// Resolve a per-project task URL key (a numeric #num, or a raw task id) → task id.
async function resolveProjectTaskKey(projectId, key) {
  if (/^\d+$/.test(key)) {
    const local = (S.tasks || []).find((t) => t.projectId === projectId && String(t.num) === key);
    if (local) return local.id;
    const r = await api(`/api/projects/${projectId}/tasks/by-num/${key}`).catch(() => null);
    return r?.id ?? null;
  }
  const local = (S.tasks || []).find((t) => t.id === key);
  return local ? local.id : key; // raw-id fallback
}

// Cross-project/organization navigation may genuinely need data that is not in
// memory. It still owns the main cell synchronously, so the previous page never
// masquerades as an ignored click while those requests run.
function renderRouteLoadingPage(title, label = 'Loading…') {
  const main = $('#main');
  if (!main) return;
  main.innerHTML = `<div class="route-loading" role="status" aria-busy="true">
    <b>${esc(title || 'Opening')}</b>
    <span class="global-search-loading">${esc(label)}</span>
  </div>`;
}

async function applyRoute() {
  const routeEpoch = S.routeEpoch = (S.routeEpoch || 0) + 1;
  const routePath = location.pathname;
  const routeIsCurrent = () => S.routeEpoch === routeEpoch && location.pathname === routePath;
  const r = parseRoute(currentPath());
  const renamed = renamedOrganizationPath(r);
  if (renamed) return go(renamed, { replace: true });
  if (r.name === 'home') {
    const org = currentOrg();
    return go(org ? homeRoute(org, DEFAULT_LIST_QUERY) : globalRoute('insights'), { replace: true });
  }
  if (r.name === 'profile') {
    if (r.legacy) return go(`${profileRoute()}${location.hash || ''}`, { replace: true });
    closeTaskDom();
    if (r.userId && r.userId !== S.user?.id && !S.installationAccess)
      return go(profileRoute(), { replace: true });
    S.profileUserId = r.userId || null;
    S.tab = 'profile';
    renderRail();
    renderMain();
    return;
  }
  if (r.name === 'installation') {
    if (!S.installationAccess) return go(globalRoute('insights'), { replace: true });
    closeTaskDom();
    S.tab = 'installation';
    renderRail();
    renderMain();
    return;
  }
  if (r.name === 'global') {
    // Select the organization named in the URL (if any) before painting.
    if (r.org) {
      const org = organizationBySlug(r.org);
      if (!org) { toast('Organization not found', true); return go('/', { replace: true }); }
      const organizationChanged = org.id !== S.organizationId;
      if (organizationChanged) {
        S.organizationId = org.id;
        S.projectId = S.projects.find((p) => p.organizationId === org.id)?.id || null;
        syncLiveWatch();
        renderOnboarding();
        refreshOnboarding();
        renderRouteLoadingPage(org.name, 'Switching organization…');
      }
      syncOrganizationSwitcher();
      if (organizationChanged) {
        await loadCollaboration().catch(() => {});
        if (!routeIsCurrent()) return;
      }
    }
    await loadOrganizationRuntimeCatalog();
    if (!routeIsCurrent()) return;
    // Bare /<org> is the organization home: one task list over all its projects.
    if (r.tab === 'home' && S.organizationId) return applyHomeRoute(r, routeIsCurrent);
    if (r.tab === 'home') r.tab = 'insights'; // a workspace with no organization yet
    if (r.tab === 'inbox') {
      if (r.legacy) return go(inboxRoute(DEFAULT_LIST_QUERY), { replace: true });
      return applyListRoute('inbox', 'all', r, routeIsCurrent);
    }
    // Pre-org URLs (/dashboard, /organization, …) → rewrite to the org-prefixed
    // form below. Only redirect when the canonical path actually differs, so an
    // unresolvable slug renders instead of looping.
    if (r.legacy) {
      const dest = globalRoute(r.tab);
      if (dest !== location.pathname) return go(dest, { replace: true });
    }
    closeTaskDom();
    S.tab = r.tab;
    renderRail();
    // renderMain() already dispatches per-tab hydration (renderInsights,
    // hydrateOrganizationView, …). Calling them again here double-ran hydration
    // on the same DOM, stacking a second click listener on static buttons like
    // "Invite" — which sent every invitation (and its email) twice and rendered
    // the pending list twice. One dispatch only.
    renderMain();
    return;
  }
  // project / task routes → resolve the org + project (by name-slug) + optional open task
  const previousOrganizationId = S.organizationId;
  let routeOrganization = null;
  if (r.org) {
    routeOrganization = organizationBySlug(r.org);
    if (!routeOrganization) { toast('Organization not found', true); return go('/', { replace: true }); }
    S.organizationId = routeOrganization.id;
  }
  const proj = projectBySlug(r.slug, routeOrganization?.id);
  if (!proj) { toast('Project not found', true); return go('/', { replace: true }); }
  // Pre-organization /projects/:name/… → rewrite to the org-prefixed permalink.
  if (r.legacy) {
    const dest = r.taskKey
      ? r.taskFile
        ? `${projectBase(proj.id)}/tasks/${r.taskKey}/file?${fileTargetQuery(r.taskFile)}`
        : `${projectBase(proj.id)}/tasks/${r.taskKey}${r.taskTab ? `/${r.taskTab}` : ''}`
      : projectRoute(proj.id, r.tab, r.q);
    return go(dest, { replace: true });
  }
  const pid = proj.id;
  const sameProject = pid === S.projectId;
  const selectedRecord = taskRecord(S.selected);
  const selectedKey = selectedRecord && String(selectedRecord.num ?? selectedRecord.id);
  if (r.taskKey && selectedKey !== String(r.taskKey))
    renderRouteLoadingPage(`Task ${/^\d+$/.test(r.taskKey) ? `#${r.taskKey}` : ''}`.trim(), 'Loading task…');
  else if (!r.taskKey && !sameProject)
    renderRouteLoadingPage(proj.name, 'Loading project…');
  S.organizationId = proj.organizationId || S.organizationId;
  syncOrganizationSwitcher();
  if (S.organizationId !== previousOrganizationId) {
    renderOnboarding();
    refreshOnboarding();
    await loadCollaboration().catch(() => {});
    if (!routeIsCurrent()) return;
  }
  await loadOrganizationRuntimeCatalog();
  if (!routeIsCurrent()) return;
  const tab = r.tab || 'tasks';
  S.wikiView = r.wikiView || '';
  if (!sameProject) {
    // Switching projects: drop the previous project's per-project view state so
    // its query/roving-cursor/search-result can't bleed into the new project
    // (they'd otherwise re-run the old query against new data and highlight a
    // view/cursor that doesn't exist here). The incoming URL's own ?q= is applied
    // below, so a link into another project's search still lands filtered.
    S.projectId = pid;
    syncLiveWatch();
    S.cursorId = null;
  }
  // The list query belongs to one list (a project, or the organization home);
  // arriving from another drops it, so it cannot leak into this one's links.
  if (S.searchScope !== pid) {
    S.search = DEFAULT_LIST_QUERY;
    S.searchScope = pid;
    S.searchResult = null;
    S.searchPending = false;
  }
  const incomingListQuery = r.q ?? DEFAULT_LIST_QUERY;
  const projectOrganizationLoaded = sameProject && S.orgProjectId === pid;
  const canPaintCachedProject = !r.taskKey && projectOrganizationLoaded;
  // A project with nothing in memory to paint reads everything its page needs
  // together: tasks, avatars, tags/views and the list's search (RQ-9).
  const reads = [];
  if (!sameProject || !S.tasks?.length) reads.push(loadTasks().catch(() => {}));
  if (!sameProject || !S.avatarAvailability || S.avatarProjectId !== pid) reads.push(loadAvatars().catch(() => {}));
  // The URL owns the open Avatar, as it owns the open task.
  S.avatarSelected = tab === 'avatars' ? r.avatarId || null : null;
  S.avatarAuthorizationRequests = [];
  if (S.avatarSelected) reads.push(loadAvatarAuthorizationRequests(S.avatarSelected));
  let organizationRead = null, listSearch = null;
  if (!projectOrganizationLoaded) {
    organizationRead = loadOrg().catch(() => false);
    if (!r.taskKey && tab === 'tasks') {
      S.search = incomingListQuery;
      listSearch = runSearch().catch(() => {});
    }
  }
  await Promise.all(reads);
  if (!routeIsCurrent()) return;
  if (S.avatarSelected && !S.avatars.some((avatar) => avatar.id === S.avatarSelected)) {
    toast('Avatar not found', true);
    return go(avatarRoute(pid), { replace: true });
  }
  // Same-project tabs are local navigation. Their complete last-painted inputs
  // are already in memory, so reveal the destination before refreshing tags,
  // views, fields, and (for the task list) the authoritative search result.
  // A changed task-list query clears the previous server result and paints a
  // labelled local preview instead of flashing unrelated rows.
  if (canPaintCachedProject) {
    S.tab = tab;
    closeTaskDom();
    if (tab === 'tasks' && incomingListQuery !== S.search) {
      S.search = incomingListQuery;
      S.searchResult = null;
      S.searchFailed = false;
      S.searchPending = true;
    }
    renderRail();
    renderMain();
    if (tab === 'activity') seedActivity();
    if (tab === 'queue') seedQueue();
  }
  // Tags / saved views / field registry. A task page in a project whose metadata
  // is loaded re-reads none of it, so opening or j/k-walking tasks costs only the
  // task's own reads (UI-6); the list refreshes it when shown again. First visits
  // and cross-project routes wait so they never render foreign tags.
  if (!r.taskKey || !projectOrganizationLoaded) await (organizationRead || loadOrg().catch(() => false));
  if (!routeIsCurrent()) return;
  // Resolve the open task from the URL BEFORE painting, so a permalink paints once
  // (its task page), not the list with a page swapped in a beat later.
  let taskId = null;
  if (r.taskKey) {
    taskId = await resolveProjectTaskKey(pid, r.taskKey);
    if (!routeIsCurrent()) return;
    if (!taskId) toast(`Task #${r.taskKey} not found`, true);
  }
  S.tab = tab;
  if (!taskId) closeTaskDom();
  if (tab === 'tasks' && !taskId) {
    // The list is query-driven and the URL owns the query: a pasted, bookmarked,
    // reloaded or Back-navigated link paints the same filtered/grouped/sorted view.
    S.search = incomingListQuery;
    await (listSearch || runSearch().catch(() => {}));
    if (!routeIsCurrent()) return;
  }
  renderRail();
  if (taskId) {
    const nextTaskFile = r.taskFile || null;
    if (JSON.stringify(S.taskFile) !== JSON.stringify(nextTaskFile)) S.taskFileLoad = null;
    S.taskFile = nextTaskFile;
    if (S.selected !== taskId) return openTask(taskId, r.taskTab, r.taskKey === taskId);
    S.viewingAttempt = r.taskKey === taskId ? taskId : null;
    if (r.taskTab) S.taskTab = r.taskTab;
    showDraftPage(taskId);
    return renderTaskPage();
  }
  S.taskFile = null;
  if (canPaintCachedProject && tab !== 'tasks') return;
  renderMain();
  if (tab === 'activity') seedActivity();
  if (tab === 'queue') seedQueue();
}

// The organization home: the task list over every project of the organization,
// with the same query language, views and toolbar as a project list. The URL
// owns its query exactly as it owns a project list's.
async function applyHomeRoute(r, routeIsCurrent) {
  return applyListRoute('home', `org:${S.organizationId}`, r, routeIsCurrent);
}
// A list over many projects: the organization home, or the bell's page over
// every organization (scope 'all').
async function applyListRoute(tab, scope, r, routeIsCurrent) {
  closeTaskDom();
  S.tab = tab;
  const query = r.q ?? DEFAULT_LIST_QUERY;
  if (S.searchScope !== scope || S.search !== query) {
    S.search = query;
    S.searchScope = scope;
    S.searchResult = null;
    S.searchFailed = false;
    S.searchPending = true;
    S.cursorId = null;
  }
  renderRail();
  renderMain();
  const readable = firstProjectForOrganization(S.organizationId);
  const fields = S.fields.length || !readable ? null
    : api(`/api/search/fields?projectId=${encodeURIComponent(readable.id)}`).then((value) => { S.fields = value || []; }).catch(() => {});
  await Promise.all([runSearch().catch(() => {}), fields]);
  if (!routeIsCurrent() || S.tab !== tab) return;
  renderMain();
}

// The permalink for a task (/<org>/<project>/tasks/:num) — used for in-place
// navigation and for "open in a new tab" (Ctrl/⌘-click, middle-click). It stays
// free of the list's ?q=: a task link is about the task, and the query you came
// from is remembered in S.returnRoute (and in the history entry behind you).
function taskUrl(id, record) {
  const rec = record || taskRecord(id);
  const p = projectById(rec?.projectId || S.projectId);
  const keyPart = S.viewingAttempt !== id && rec && rec.num != null ? String(rec.num) : id;
  return p ? `${projectBase(p.id)}/tasks/${keyPart}` : currentPath();
}

// True when a click means "open in a new tab/window" by browser convention: any
